<script setup>import { Head, Link, useForm } from '@inertiajs/vue3'; import AdminLayout from '@/Layouts/AdminLayout.vue'; const props = defineProps({ payment: Object }); const form = useForm({ status: '', admin_note: '' }); const decide = status => { form.status = status; form.put(route('admin.payments.update', props.payment.id)); };</script>
<template><Head title="Periksa Pembayaran"/><AdminLayout><Link :href="route('admin.payments.index')" class="text-sm font-semibold text-aski-700">← Kembali</Link><div class="card mt-6 max-w-3xl p-7"><p class="text-sm font-semibold text-aski-700">PEMBAYARAN #{{ payment.id }}</p><h1 class="mt-1 text-3xl font-bold text-aski-900">{{ payment.user.name }}</h1><p class="text-slate-500">Tagihan {{ payment.invoice.number }}</p><a :href="route('admin.payments.proof', payment.id)" target="_blank" class="btn-primary mt-6">Lihat Bukti Pembayaran</a><div v-if="payment.status === 'submitted'" class="mt-6"><textarea v-model="form.admin_note" rows="4" placeholder="Catatan (wajib jika ditolak)" class="w-full rounded-lg border-slate-300 focus:border-aski-500 focus:ring-aski-500"></textarea><p class="text-xs text-red-600">{{ form.errors.admin_note }}</p><div class="mt-3 flex gap-2"><button class="btn-primary" @click="decide('verified')">Terima</button><button class="rounded-lg bg-red-600 px-4 py-2 text-sm font-semibold text-white" @click="decide('rejected')">Tolak</button></div></div><p v-else class="mt-6 text-sm">Status: <b>{{ payment.status }}</b></p></div></AdminLayout></template>
